module accu(
    input clk, input rst_n, input [7:0] data_in, input valid_in,
    output reg valid_out, output reg [9:0] data_out
);
// Internal registers
reg [1:0] cnt;
reg [9:0] data_out_reg;
reg valid_out_reg;
// Sequential logic block triggered on positive edge of clk or negative edge of rst_n
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        // Reset condition: Set all registers to zero
        cnt <= 0;
        data_out_reg <= 0;
        valid_out_reg <= 0;
    end else begin
        // Check if valid_in is asserted
        if (valid_in == 1) begin
            // Increment counter if less than 4
            if (cnt < 4) begin
                cnt <= cnt + 1;
                // Add current data_in value to accumulator
                data_out_reg <= data_out_reg + data_in;
            end else begin
                // Reset counter after reaching 4
                cnt <= 0;
                // Set valid_out_reg to indicate completion of accumulation
                valid_out_reg <= 1;
            end
        end else begin
            // Reset valid_out_reg if valid_in is not asserted
            valid_out_reg <= 0;
        end
    end
end
// Assigning the output ports to their respective registers
assign valid_out = valid_out_reg;
assign data_out = data_out_reg;
endmodule
